 55→const useQuery = <D extends object>(
 56→  { table, query, status, setStatus, handleResult }: UseQueryParams<D>,
 57→  deps: Array<unknown> = [],
 58→) => {
 59→  // Keep track of the latest query being performed
 60→  const latestQuery = React.useRef<null | Promise<DataTableQueryResult<D>>>(null);
 61→  
 62→  useEffectAsync(async () => {
 63→    try {
 64→      setStatus(status => ({ ...status, loading: true, error: null }));
 65→      
 66→      const queryPromise = query({
 67→        pageIndex: table.state.pageIndex,
 68→        pageSize: table.state.pageSize,
 69→        offset: table.state.pageIndex * table.state.pageSize,
 70→        limit: table.state.pageSize,
 71→        sortBy: table.state.sortBy,
 72→        orderings: table.state.sortBy.map(({ id, desc }) =>
 73→          ({ column: id, direction: desc ? 'DESC' : 'ASC' }),
 74→        ),
 75→        globalFilter: table.state.globalFilter,
 76→        filters: table.state.filters,
 77→      });
 78→      latestQuery.current = queryPromise;
 79→      const queryResult = await queryPromise;
 80→      
 81→      // Note: only update if we haven't been "superseded" by a more recent update
 82→      if (latestQuery.current !== null && latestQuery.current === queryPromise) {
 83→        setStatus({ ready: true, loading: false, error: null });
 84→        handleResult(queryResult);
 85→      }
 86→    } catch (reason: unknown) {
 87→      console.error(reason);
 88→      const error = reason instanceof Error ? reason : new Error('Unknown error');
 89→      setStatus({ ready: false, loading: false, error });
 90→      //handleResult({ total: 0, itemsPage: [] });
 91→    }
 92→  }, [
 93→    setStatus,
 94→    query,
 95→    table.state.pageIndex,
 96→    table.state.pageSize,
 97→    table.state.sortBy,
 98→    table.state.globalFilter,
 99→    table.state.filters,
100→    ...deps,

