 5→import * as React from 'react';
 6→
 7→
 8→type TimeoutRef = ReturnType<typeof globalThis.setTimeout>;
 9→type UseDebounceResult<S> = [S, React.Dispatch<React.SetStateAction<S>>];
10→
11→// Adopted from: https://github.com/uidotdev/usehooks
12→export const useDebounce = <S>(value: S, delay: number /* ms */): UseDebounceResult<S> => {
13→  const [debouncedValue, setDebouncedValue] = React.useState(value);
14→  const timeoutHandleRef = React.useRef<TimeoutRef>(null);
15→  
16→  // Whenever `value` changes, schedule an update after `delay` ms
17→  React.useEffect(() => {
18→    if (delay === 0) {
19→      setDebouncedValue(value);
20→      
21→      const timeoutHandle = timeoutHandleRef.current;
22→      if (timeoutHandle) {
23→        globalThis.clearTimeout(timeoutHandle);
24→      }
25→      
26→      return;
27→    }
28→    
29→    timeoutHandleRef.current = globalThis.setTimeout(() => {
30→      setDebouncedValue(value);
31→    }, delay);
32→    
33→    return () => {
34→      const timeoutHandle = timeoutHandleRef.current;
35→      if (timeoutHandle) {
36→        globalThis.clearTimeout(timeoutHandle);
37→      }
38→    };
39→  }, [value, delay]);
40→  
41→  // Expose a way to force the debounced value manually
42→  const setDebouncedManually = React.useCallback((value: React.SetStateAction<S>) => {
43→    setDebouncedValue(value);
44→    
45→    const timeoutHandle = timeoutHandleRef.current;
46→    if (timeoutHandle) {
47→      globalThis.clearTimeout(timeoutHandle);
48→    }
49→  }, []);
50→  
51→  return [debouncedValue, setDebouncedManually];
52→};
